CREATE OR REPLACE FUNCTION buildpulse_reject_story(p_story_id UUID,p_reviewer TEXT,p_notes TEXT) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_state TEXT; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'service role required'; END IF; IF coalesce(trim(p_reviewer),'')='' OR coalesce(trim(p_notes),'')='' THEN RAISE EXCEPTION 'reviewer and reason required'; END IF; SELECT verification_state INTO old_state FROM buildpulse_stories WHERE id=p_story_id FOR UPDATE; IF old_state IS NULL THEN RETURN FALSE; END IF; IF old_state NOT IN ('pending','needs_review') THEN RAISE EXCEPTION 'story is not reviewable'; END IF; UPDATE buildpulse_stories SET verification_state='rejected',verification_notes=p_notes,verified_at=NULL,verified_by=lower(trim(p_reviewer)),canonical_source_url=NULL WHERE id=p_story_id; INSERT INTO buildpulse_review_events(story_id,action,actor,notes) VALUES(p_story_id,'reject',lower(trim(p_reviewer)),p_notes); RETURN TRUE; END $$; REVOKE ALL ON FUNCTION buildpulse_reject_story(UUID,TEXT,TEXT) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION buildpulse_reject_story(UUID,TEXT,TEXT) TO service_role;